// usage mod ("Consommation"): read-only view of what the agents burn and when the plan's windows run out.
// /conso [aujourdhui|semaine|prevision|scenarios|plein|classement] [refresh] opens the pane. Tokens come from the local
// transcripts (scanner/usage_scan.mjs, incremental, run with Node); the official 5-hour and weekly % come from
// $.session.usage().rateLimits and the session.measure event, saved as samples to calibrate tokens per 1 %.
// Nothing here blocks or rewrites anything: session.measure passes on untouched, the scenarios are only suggested.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import { tokensOf } from '../lib/transcripts.mjs'
import { CV, codexView } from '../lib/codex.mjs'
import { bar, codexTokens, isAppLink, linksFromFil, rank, trendText } from '../lib/classement.mjs'
import { deepMerge, expandHome, fmtPct, fmtTokens, fmtUsd, heatRow, model, outcome, promptLine, when } from './logic.mjs'
import { historyView } from '../lib/history.mjs'
import { fmtDur, fmtTps, recentStreams, shortModel, tpsTable } from '../lib/tps.mjs'

const TABS = ['today', 'week', 'classement', 'history', 'tps', 'forecast', 'scenarios', 'full', 'codex'] as const
const ALIASES: Record<string, string> = { aujourdhui: 'today', today: 'today', semaine: 'week', week: 'week', prevision: 'forecast', forecast: 'forecast', scenarios: 'scenarios', plein: 'full', full: 'full', codex: 'codex', classement: 'classement', qui: 'classement', ranking: 'classement', historique: 'history', history: 'history', debit: 'tps', tps: 'tps' }
const tab = atom({ plugin: 'usage', key: 'tab' } as const, 'today')
const copied = atom({ plugin: 'usage', key: 'copied' } as const, '')
const cPreset = atom({ plugin: 'usage', key: 'preset' } as const, '')
const cGroup = atom({ plugin: 'usage', key: 'group' } as const, '')
const hPreset = atom({ plugin: 'usage', key: 'history' } as const, '')
const tBy = atom({ plugin: 'usage', key: 'tps_by' } as const, '')
// '' = codex.show_default of the config (Claude only by default); 'on' / 'off' once the Codex button was pressed
const showCx = atom({ plugin: 'usage', key: 'show_codex' } as const, '')

type Options = { status_line?: string; codex?: string }
const S: { busy: boolean; error: string; at: number; last: any; aggr: any; cls: any; quotas: string } = { busy: false, error: '', at: 0, last: undefined, aggr: undefined, cls: undefined, quotas: '' }

// Hands a desktop-app conversation link to the OS (same rule and call as veille's Fil). Windows: url.dll, no shell.
async function openUrl($: EngineInterface, url: string) {
  if (!isAppLink(url)) return false
  let win = false
  try { win = (await $.env.get('OS')) === 'Windows_NT' } catch {}
  try {
    const r = await $.process.run(win ? ['rundll32.exe', 'url.dll,FileProtocolHandler', url] : ['xdg-open', url], { timeoutMs: 10000 })
    return r.exitCode === 0
  } catch {
    return false
  }
}

const home = async ($: EngineInterface) => {
  let v: string | undefined
  try {
    v = (await $.env.get('USERPROFILE')) || (await $.env.get('HOME'))
  } catch {}
  return (v ?? '').replace(/\\/g, '/')
}
const readJson = async ($: EngineInterface, path: string): Promise<any> => {
  try {
    return JSON.parse((await $.fs.read(path, { as: 'text' })) as string)
  } catch {
    return undefined
  }
}

async function context($: EngineInterface, options: Options) {
  const root = $.plugin.root.replace(/\\/g, '/')
  const h = await home($)
  const base = (await readJson($, `${root}/usage.config.json`)) || {}
  const dataDir = expandHome(base.data_dir || '~/.claude/usage-mod', h)
  const cfg = deepMerge(base, (await readJson($, `${dataDir}/usage.config.json`)) || {})
  if (options.status_line === 'on' || options.status_line === 'off') cfg.status_line = options.status_line
  if (options.codex === 'on' || options.codex === 'off') cfg.codex = { ...(cfg.codex || {}), enabled: options.codex }
  return { root, dataDir, cfg }
}

async function samples($: EngineInterface, dataDir: string) {
  try {
    const text = (await $.fs.read(`${dataDir}/samples.jsonl`, { as: 'text' })) as string
    return text.split('\n').filter(Boolean).map(l => { try { return JSON.parse(l) } catch { return null } }).filter(Boolean)
  } catch {
    return []
  }
}

async function liveLimits($: EngineInterface) {
  try {
    return (await $.session.usage()).rateLimits ?? []
  } catch {
    return []
  }
}

/** Runs the scanner (incremental) and redraws; never awaited by a hook that the person waits on. */
async function rescan($: EngineInterface, options: Options) {
  if (S.busy) return
  S.busy = true
  try {
    const { root, cfg } = await context($, options)
    const r = await $.process.run([cfg.node || 'node', `${root}/scanner/usage_scan.mjs`, 'scan', '--codex-enabled', String(cfg.codex?.enabled ?? 'auto')], { timeoutMs: Math.min((cfg.scan_timeout_s ?? 600) * 1000, 600000) })
    if (r.exitCode !== 0) throw new Error((r.stderr || '').trim().split('\n').pop() || `scanner exit ${r.exitCode}`)
    S.error = ''
    S.at = await $.clock.now()
    await loadQuotas($, options)
    S.aggr = undefined
    S.cls = undefined
  } catch (err) {
    S.error = String((err as Error)?.message ?? err).slice(0, 300)
  } finally {
    S.busy = false
  }
  await refreshStatus($, options)
  $.ui.invalidate('ui.render')
}

/** The 5 h / week line of lib/core/usage.mjs (scanner/usage_scan.mjs quotas): the numbers band and cockpit print. */
async function loadQuotas($: EngineInterface, options: Options) {
  try {
    const { root, cfg } = await context($, options)
    const r = await $.process.run([cfg.node || 'node', `${root}/scanner/usage_scan.mjs`, 'quotas'], { timeoutMs: 30000 })
    if (r.exitCode === 0) S.quotas = String(JSON.parse(r.stdout).line || '')
  } catch {}
}

async function compute($: EngineInterface, options: Options, current = '') {
  const { root, dataDir, cfg } = await context($, options)
  const aggr = S.aggr ?? (S.aggr = await readJson($, `${dataDir}/aggregate.json`))
  const sc = await readJson($, `${root}/${cfg.scenarios_file || '../scenarios/scenarios.json'}`)
  const now = await $.clock.now()
  const codexOff = cfg.codex?.enabled === 'off'
  const pick = String((await read($, showCx)) || '')
  // Claude only unless the Codex button was pressed or codex.show_default is true
  const showCodex = !codexOff && (pick ? pick === 'on' : cfg.codex?.show_default === true)
  const cxFile = codexOff ? undefined : await readJson($, `${dataDir}/codex.json`)
  const cx = codexOff ? { available: false, reason: 'off' } : codexView(cxFile, cfg, { now, tzMin: aggr?.tzMin ?? 0 })
  const m = aggr ? model(aggr, cfg, { now, live: await liveLimits($), samples: await samples($, dataDir), scenarios: sc?.scenarios ?? [] }) : undefined
  const cls = current === 'classement' ? S.cls ?? (S.cls = await readJson($, `${dataDir}/classement.json`)) : undefined
  const cxRaw = (current === 'classement' || current === 'tps') && showCodex ? cxFile : undefined
  const hist = current === 'history' ? await readJson($, `${dataDir}/history.json`) : undefined
  return { cfg, m, sc, cx, cxRaw, cls, hist, aggr, now, showCodex, codexOff, stale: !aggr || now - S.at > (cfg.refresh_min ?? 10) * 60000 }
}

async function refreshStatus($: EngineInterface, options: Options) {
  const { cfg, m } = await compute($, options)
  if (cfg.status_line !== 'on') return
  $.ui.status(m?.status)
}

export const register: Register = (on, raw) => {
  const options = (raw ?? {}) as Options

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'conso',
      description: 'Consommation : tokens, coût équivalent, prévision des limites 5 h et semaine, scénarios (args: [aujourdhui|semaine|prevision|scenarios|plein] [refresh])',
      argumentHint: '[aujourdhui|semaine|prevision|scenarios|plein] [refresh] | close',
    })
    const { cfg } = await context($, options)
    if (cfg.status_line === 'on') $.clock.after(2000, () => rescan($, options))
    return next(e)
  })

  on('command.run', { command: 'conso' }, async ($, e) => {
    if ((e.args ?? '').trim().toLowerCase() === 'close') {
      await $.ui.close({ id: 'usage' })
      return {}
    }
    const words = String(e.args ?? '').toLowerCase().split(/\s+/).filter(Boolean)
    const want = words.map(w => ALIASES[w.normalize('NFD').replace(/[̀-ͯ']/g, '')]).find(Boolean)
    if (want) await update($, tab, () => want)
    const { cfg, m, cx, stale, showCodex } = await compute($, options)
    if (!S.quotas) await loadQuotas($, options)
    if (stale || words.includes('refresh')) $.clock.after(0, () => rescan($, options))
    await $.ui.open({ id: 'usage', title: cfg.labels?.pane_title ?? 'usage' })
    const l = cfg.labels ?? {}
    if (!m) return { text: `conso: premier scan en cours (${cfg.projects_dir})` }
    const week = m.week ? `${l.week_label} ${fmtPct(m.week.reading.pct)} · ${outcome(m.week.current, m.tz, l)} ${l.pace_now}` : l.no_reading
    const cxl = cfg.codex?.labels ?? {}
    const codex = !showCodex ? '' : ` · ${cxl.codex ?? 'Codex'} ${cx.available && cx.hasData ? `${fmtTokens(cx.today.total[CV.total])} tokens${cx.windows[0] ? ` · ${cx.windows[0].label} ${fmtPct(cx.windows[0].pct)}` : ''}` : cxl.unavailable ?? 'non disponible'}`
    return { text: `conso: aujourd'hui ${fmtTokens(tokensOf(m.today.total))} tokens · ${fmtUsd(m.today.total[7])} · ${week}${codex}${S.quotas ? `\nquotas : ${S.quotas}` : ''}` }
  })

  // Observe only: save a sample when a rate-limit window moved, refresh the status line. The event passes on unchanged.
  on('session.measure', async ($, e, next) => {
    const result = await next(e)
    if ((e.changed ?? []).includes('rateLimits') && (e.rateLimits ?? []).length) {
      const sample: Record<string, unknown> = {}
      for (const r of e.rateLimits) {
        if (r.kind === 'seven_day' || r.kind === 'five_hour') sample[r.kind] = { pct: r.percentUsed, reset: r.resetsAt ? Date.parse(r.resetsAt) : undefined }
      }
      $.clock.after(0, async () => {
        const { root, cfg } = await context($, options)
        await $.process.run([cfg.node || 'node', `${root}/scanner/usage_scan.mjs`, 'sample', JSON.stringify(sample)], { timeoutMs: 30000 })
        await refreshStatus($, options)
      })
    }
    return result
  }).catch(($, e, next) => next(e)) // fail open: a failing sample never stops the measurement

  on('ui.render', { component: 'Pane', requestId: 'usage' }, async ($, e) => {
    const { Box, Text, Button, Code } = $.ui.resolve(e)
    const current = ((await read($, tab)) as string) || 'today'
    const { cfg, m, sc, cx, cxRaw, cls, hist, aggr, now, showCodex, codexOff } = await compute($, options, current)
    const l = cfg.labels ?? {}
    const cxl = cfg.codex?.labels ?? {}
    const fill = (t: string, v: Record<string, string>) => String(t ?? '').replace(/\{(\w+)\}/g, (_, k) => v[k] ?? `{${k}}`)
    const dir = String(cfg.codex?.sessions_dir ?? '~/.codex/sessions')
    const cxTokens = (v: number[]) => `${fmtTokens(v[CV.total])} tokens (entrée ${fmtTokens(v[CV.input])} dont cache ${fmtTokens(v[CV.cached])} · sortie ${fmtTokens(v[CV.output])} dont raisonnement ${fmtTokens(v[CV.reasoning])})`
    const cxOk = cx.available && cx.hasData
    const last = await read($, copied)
    const unit = m?.basis === 'tokens' ? 'tokens' : '$'
    const amount = (v: number[]) => `${fmtTokens(tokensOf(v))} tokens · ${fmtUsd(v[7])}`
    const rows = (title: string, xs: { key: string; v: number[] }[], n = 10, label = (k: string) => k) => (
      <Box flexDirection="column">
        <Text bold>{title}</Text>
        {xs.length === 0 ? <Text dimColor>  —</Text> : xs.slice(0, n).map(x => <Text>{`  ${label(x.key).slice(0, 48).padEnd(48)} ${amount(x.v)}`}</Text>)}
      </Box>
    )
    const header = (
      <Box flexDirection="column">
        <Text dimColor>{`${cfg.plan_label ?? cfg.plan} · lecture seule · coûts : ${l.estimate}${S.busy ? ' · scan en cours…' : ''}`}</Text>
        {S.error ? <Text color="error">{`scan: ${S.error}`}</Text> : null}
        {S.quotas ? <Text key="quotas">{`${l.quotas_label ?? 'Quotas'} : ${S.quotas}`}</Text> : null}
        {m && !showCodex ? <Text>{`${cxl.claude ?? 'Claude'} aujourd'hui ${fmtTokens(tokensOf(m.today.total))} tokens · 7 j ${fmtTokens(tokensOf(m.weekView.total))}`}</Text> : null}
        {m && showCodex ? (
          <Text>{`${cxl.claude ?? 'Claude'} aujourd'hui ${fmtTokens(tokensOf(m.today.total))} tokens · 7 j ${fmtTokens(tokensOf(m.weekView.total))}  |  ${cxl.codex ?? 'Codex'} ${cxOk ? `aujourd'hui ${fmtTokens(cx.today.total[CV.total])} tokens · 7 j ${fmtTokens(cx.week.total[CV.total])}${cx.windows.map((w: any) => ` · ${w.label} ${fmtPct(w.pct)}`).join('')}` : cxl.unavailable ?? 'non disponible'}`}</Text>
        ) : null}
        <Box flexDirection="row" gap={1} flexWrap="wrap">
          {TABS.filter(t => t !== 'codex' || showCodex).map(t => (
            <Button key={`tab-${t}`} {...(t !== current ? { plain: true as const } : {})} onPress={() => update($, tab, () => t)}>
              {l.tabs?.[t] ?? (t === 'classement' ? 'Classement' : t)}
            </Button>
          ))}
          {codexOff ? null : (
            <Button key="codex-toggle" {...(showCodex ? {} : { plain: true as const })} onPress={async () => {
              await update($, showCx, () => (showCodex ? 'off' : 'on'))
              if (showCodex && current === 'codex') await update($, tab, () => 'today')
            }}>{showCodex ? cxl.hide ?? '− Codex' : cxl.show ?? '+ Codex'}</Button>
          )}
          <Button key="refresh" plain onPress={() => { $.clock.after(0, () => rescan($, options)) }}>↻</Button>
        </Box>
      </Box>
    )
    if (!m) return <Box flexDirection="column" gap={1}>{header}<Text>Pas encore de données : le premier scan lit les transcripts des derniers jours.</Text></Box>

    const kindLabel = (k: string) => l.kinds?.[k] ?? k
    const sessionLabel = (sid: string) => {
      const s = S.aggr?.sessions?.[sid]
      return s ? `${s.title || sid.slice(0, 8)} (${s.project})` : sid.slice(0, 8)
    }
    const period = (p: any, week: boolean) => (
      <Box flexDirection="column" gap={1}>
        <Text bold>{`Total : ${amount(p.total)}`}</Text>
        {week ? rows('Par jour', p.perDay.map((d: any) => ({ key: d.day, v: d.v })), 7) : null}
        <Box flexDirection="column">
          <Text bold>Par heure (carte de chaleur, 7 jours)</Text>
          {(() => {
            const max = Math.max(...m.heat.grid.flat(), 0)
            return m.heat.grid.map((row: number[], i: number) => (
              <Text>{`  ${when(m.heat.start + i * 86400000 + 43200000, m.tz, l, true).split(' ')[0]} |${heatRow(row, max, cfg.heat)}|`}</Text>
            ))
          })()}
          <Text dimColor>{'      0h    6h    12h   18h  23h'}</Text>
        </Box>
        {rows('Par projet', p.project)}
        {rows('Par modèle', p.model)}
        {rows('Par type', p.kind, 10, kindLabel)}
        {rows("Par surface de l'app", p.surface)}
        {rows('Par effort', p.effort)}
        {rows('Par skill', p.skill)}
        {rows('Par serveur MCP', p.mcp)}
        {rows(week ? 'Top 10 des sessions de la semaine' : 'Sessions', p.session, 10, sessionLabel)}
      </Box>
    )

    const fc = (title: string, w: any) =>
      !w ? <Text>{`${title} : ${l.no_reading}`}</Text> : (
        <Box flexDirection="column">
          <Text bold>{`${title} : ${fmtPct(w.reading.pct)} utilisés · reset ${when(w.reading.reset, m.tz, l)}${w.reading.live ? '' : ' (dernier échantillon)'}`}</Text>
          <Text>{`  ${l.pace_now} : ${outcome(w.current, m.tz, l) || 'pas assez de mesures'}`}</Text>
          {w.byRate ? Object.entries(w.byRate).map(([k, f]: any) => <Text dimColor>{`  rythme ${k === 'recent' ? '2 dernières h' : k === 'today' ? "aujourd'hui" : 'moyenne 7 j'} (${fmtPct(f?.pctPerHour)}/h) : ${outcome(f, m.tz, l)}`}</Text>) : null}
          {w.projections ? w.projections.map((p: any) => <Text>{`  ${p.label} : ${outcome(p.result, m.tz, l) || '?'}`}</Text>) : null}
        </Box>
      )

    const codexPane = () => {
      if (cx.reason === 'off') return <Text>{cxl.off}</Text>
      if (!cx.available) return <Text>{fill(cx.reason === 'no_dir' ? cxl.no_dir : `${cxl.unavailable} : {dir}`, { dir })}</Text>
      if (!cx.hasData) return <Text>{fill(cxl.no_data, { dir })}</Text>
      const byModel = (title: string, xs: { key: string; v: number[] }[]) => (
        <Box flexDirection="column">
          <Text bold>{title}</Text>
          {xs.length === 0 ? <Text dimColor>  —</Text> : xs.map(x => <Text>{`  ${x.key.slice(0, 32).padEnd(32)} ${fmtTokens(x.v[CV.total])} tokens`}</Text>)}
        </Box>
      )
      return (
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="column">
            <Text bold>{`Aujourd'hui : ${cxTokens(cx.today.total)}`}</Text>
            <Text bold>{`7 jours : ${cxTokens(cx.week.total)}`}</Text>
            <Text dimColor>{`${cx.sessions} session(s) lues${cx.model ? ` · dernier modèle ${cx.model}` : ''}${cx.plan ? ` · plan ${cx.plan}` : ''}`}</Text>
          </Box>
          <Box flexDirection="column">
            <Text bold>Limites Codex</Text>
            {cx.windows.length === 0 ? <Text>{`  ${cxl.no_limits}`}</Text> : cx.windows.map((w: any) => (
              <Text>{`  ${w.label} : ${fmtPct(w.pct)} utilisés${w.reset ? ` · reset ${when(w.reset, m.tz, l)}` : ''} · lu ${when(w.at, m.tz, l)}${w.past ? ` (${cxl.past})` : w.stale ? ` (${cxl.stale})` : ''}`}</Text>
            ))}
            {cx.missing.map((x: string) => <Text dimColor>{`  ${x} : ${cxl.unavailable}`}</Text>)}
          </Box>
          {byModel("Par modèle aujourd'hui", cx.today.model)}
          {byModel('Par modèle, 7 jours', cx.week.model)}
          <Box flexDirection="column">
            <Text bold>Par jour</Text>
            {cx.week.perDay.map((d: any) => <Text>{`  ${d.key}  ${fmtTokens(d.v[CV.total])} tokens`}</Text>)}
          </Box>
          <Text dimColor>{fill(cxl.source, { dir })}</Text>
        </Box>
      )
    }
    const classementPane = async () => {
      const c = cfg.classement ?? {}
      const cl = c.labels ?? {}
      const presets: any[] = c.presets ?? []
      const groups: any[] = c.groups ?? []
      const pid = ((await read($, cPreset)) as string) || c.default_preset || 'today'
      const g0 = ((await read($, cGroup)) as string) || c.default_group || 'conversation'
      const gid = g0 === 'source' && !showCodex ? (c.default_group && c.default_group !== 'source' ? c.default_group : 'conversation') : g0
      const preset = presets.find(p => p.id === pid) ?? presets[0] ?? { id: 'today', since: 'midnight' }
      if (!cls) return <Text>Pas encore de classement : le prochain scan écrit classement.json (↻).</Text>
      const r = rank(cls, { now, preset, group: gid, top: c.top ?? 20, basis: m.basis, labels: cl })
      const links: Record<string, any> = gid === 'conversation' ? linksFromFil(await readJson($, expandHome(c.links_file ?? '~/.claude/veille/fil.json', await home($)))) : {}
      const maxShare = r.rows[0]?.share ?? 0
      const W = c.bar_width ?? 12
      const head = (x: any) => `${fmtTokens(tokensOf(x.v))} · ${fmtUsd(x.v[7])} · ${fmtPct(x.share * 100)} ${trendText(x, cl)}`.trim()
      const split = gid === 'conversation' || gid === 'project'
      const detail = (x: any) => `entrée ${fmtTokens(x.v[0])} · sortie ${fmtTokens(x.v[1])} · cache lu ${fmtTokens(x.v[2])} · cache écrit ${fmtTokens(x.v[3] + x.v[4])}${split ? ` · ${cl.sub ?? 'sous-agents'} ${fmtPct(tokensOf(x.v) ? (100 * x.sub) / tokensOf(x.v) : 0)}` : ''}`
      const cxT = gid === 'source' && showCodex ? codexTokens(cxRaw, r.window, cls.tzMin ?? 0) : undefined
      const hours = Math.round((r.window.to - r.window.from) / 3600000)
      return (
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            {presets.map(p => <Button key={`p-${p.id}`} {...(p.id !== preset.id ? { plain: true as const } : {})} onPress={() => update($, cPreset, () => p.id)}>{p.label ?? p.id}</Button>)}
          </Box>
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            {groups.filter(g => g.id !== 'source' || showCodex).map(g => <Button key={`g-${g.id}`} {...(g.id !== gid ? { plain: true as const } : {})} onPress={() => update($, cGroup, () => g.id)}>{g.label ?? g.id}</Button>)}
          </Box>
          <Text bold>{`Total ${preset.label ?? preset.id} : ${amount(r.total)} · ${r.n} ligne(s)${r.trend !== undefined ? ` · ${trendText({ trend: r.trend }, cl)} vs les ${hours} h d'avant` : ''}`}</Text>
          <Box flexDirection="column">
            {r.rows.map((x: any, i: number) => {
              const lk = x.id ? links[x.id] : undefined
              return (
                <Box key={`r-${i}`} flexDirection="column">
                  <Text>{`${String(i + 1).padStart(2)}. ${bar(x.share, maxShare, W)} ${String(x.label).slice(0, 44)}${x.project ? ` (${x.project})` : ''} · ${head(x)}`}</Text>
                  <Text dimColor>{`    ${detail(x)}`}</Text>
                  {x.id && i < (c.buttons_top ?? 10) ? (
                    <Box flexDirection="row" gap={1}>
                      <Text dimColor>{`    ${x.id}`}</Text>
                      <Button key={`cp-${i}`} plain onPress={async press => {
                        const res = await $.ui.copy({ text: x.id, surface: press.surface })
                        await update($, copied, () => (res.isCopied ? `copié : ${x.id}` : 'copie impossible : sélectionne le texte'))
                      }}>{cl.copy ?? "Copier l'id"}</Button>
                      {lk ? <Button key={`op-${i}`} plain onPress={() => { void openUrl($, lk.link) }}>{cl.open ?? 'Ouvrir'}</Button> : null}
                    </Box>
                  ) : null}
                </Box>
              )
            })}
            {r.others ? <Text dimColor>{`    ${r.others.label} (${r.others.count}) · ${head(r.others)}`}</Text> : null}
          </Box>
          {last ? <Text dimColor>{last}</Text> : null}
          {cxT !== undefined ? <Text>{`Codex · ${fmtTokens(cxT)} tokens · ${cl.codex_note ?? ''}`}</Text> : null}
          {r.partialPrev ? <Text dimColor>{`Tendance vide : la fenêtre d'avant sort de l'historique gardé (${cls.days} j).`}</Text> : null}
          <Text dimColor>{`Sous-agents et agents de Workflow comptés dans leur conversation parente. ${cl.no_tool ?? ''} Coûts : ${l.estimate}.`}</Text>
        </Box>
      )
    }
    const historyPane = async () => {
      const hc = cfg.history ?? {}
      const hl = hc.labels ?? {}
      const presets: any[] = hc.presets ?? [{ id: '90d', label: '90 j', days: 90 }]
      const pid = ((await read($, hPreset)) as string) || hc.default_preset || presets[0]?.id
      const preset = presets.find(p => p.id === pid) ?? presets[0]
      if (!hist || !Object.keys(hist.days ?? {}).length) return <Text>{hl.empty ?? "Pas encore d'historique : le prochain scan écrit history.json (↻)."}</Text>
      const hv = historyView(hist, { now, tzMin: aggr?.tzMin ?? 0, days: preset?.days ?? 90, maxRows: hc.max_rows ?? 16 })
      const unitLabel = (hl.units ?? {})[hv.unit] ?? hv.unit
      const maxB = Math.max(...hv.buckets.map((b: any) => tokensOf(b.v)), 0)
      const W = hc.bar_width ?? 16
      const barOf = (v: number[]) => (maxB > 0 ? '█'.repeat(Math.max(tokensOf(v) > 0 ? 1 : 0, Math.round((W * tokensOf(v)) / maxB))) : '').padEnd(W)
      return (
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            {presets.map(p => <Button key={`h-${p.id}`} {...(p.id !== preset?.id ? { plain: true as const } : {})} onPress={() => update($, hPreset, () => p.id)}>{p.label ?? p.id}</Button>)}
          </Box>
          <Text bold>{`Total ${preset?.label ?? ''} : ${amount(hv.total)} · ${hv.n} jour(s) gardé(s) · depuis ${hv.first}`}</Text>
          <Box flexDirection="column">
            <Text bold>{`Par ${unitLabel}`}</Text>
            {hv.buckets.map((b: any) => <Text key={`hb-${b.key}`}>{`  ${b.key.padEnd(10)} ${barOf(b.v)} ${amount(b.v)}`}</Text>)}
          </Box>
          {rows('Par modèle', hv.model, hc.top ?? 8)}
          {rows('Par projet', hv.project, hc.top ?? 8)}
          <Text dimColor>{hl.note ?? 'Historique local (history.json du dossier du mod), gardé après le nettoyage des transcripts ; Claude seulement.'}</Text>
        </Box>
      )
    }
    const tpsPane = async () => {
      const tc = cfg.tps ?? {}
      const tl = tc.labels ?? {}
      const by = ((await read($, tBy)) as string) || tc.default_by || 'model'
      const range = tc.range_pct ?? [10, 90]
      const table = tpsTable(aggr, showCodex ? cxRaw : undefined, { by, days: cfg.view_days ?? 8, now, tzMin: aggr?.tzMin ?? 0, range })
      const name = (r: any) => `${showCodex ? `${r.source === 'codex' ? cxl.codex ?? 'Codex' : cxl.claude ?? 'Claude'} ` : ''}${shortModel(r.model, tc.aliases ?? {})}${r.effort ? ` ${r.effort}` : ''}`
      const cols = tl.columns ?? ['Modèle', 'Tokens', 'Temps', 'TPS pondéré', 'médiane', 'plage']
      const W = Math.max(14, ...table.map((r: any) => name(r).length)) + 1
      const line = (a: string[]) => `  ${a[0].padEnd(W)}${a[1].padStart(9)}${a[2].padStart(12)}${a[3].padStart(13)}${a[4].padStart(9)}${a[5].padStart(11)}`
      const streams = recentStreams(aggr, showCodex ? cxRaw : undefined, tc.recent ?? 12)
      return (
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            {(tc.groupings ?? [{ id: 'model', label: 'par modèle' }, { id: 'effort', label: 'par modèle et effort' }]).map((g: any) => (
              <Button key={`t-${g.id}`} {...(g.id !== by ? { plain: true as const } : {})} onPress={() => update($, tBy, () => g.id)}>{g.label ?? g.id}</Button>
            ))}
          </Box>
          <Box flexDirection="column">
            <Text bold>{line(cols)}</Text>
            {table.length === 0 ? <Text dimColor>  —</Text> : table.map((r: any, i: number) => (
              <Text key={`tr-${i}`}>{line([name(r), fmtTokens(r.out), fmtDur(r.ms), fmtTps(r.weighted), fmtTps(r.median), `${fmtTps(r.lo)}–${fmtTps(r.hi)}`])}</Text>
            ))}
          </Box>
          <Box flexDirection="column">
            <Text bold>{tl.recent_title ?? 'Derniers flux'}</Text>
            {streams.length === 0 ? <Text dimColor>  —</Text> : streams.map((x: any, i: number) => (
              <Text key={`ts-${i}`}>{`  ${fill(tl.stream ?? '{model} {effort} : {tps} TPS ({tokens} tokens en {time})', { model: `${showCodex ? `${x.source === 'codex' ? cxl.codex ?? 'Codex' : cxl.claude ?? 'Claude'} ` : ''}${shortModel(x.model, tc.aliases ?? {})}`, effort: x.effort || '?', tps: fmtTps(x.tps), tokens: String(x.out), time: fmtDur(x.ms) })}`}</Text>
            ))}
          </Box>
          <Text dimColor>{fill(tl.note ?? 'TPS = tokens de sortie (réflexion comprise) ÷ temps du flux, attente du 1er token comprise. Pondéré = tous les tokens ÷ tout le temps ; médiane et plage (p{lo}–p{hi}) par flux, à ±7 %. Flux de moins de 50 tokens de sortie exclus. {days} derniers jours.', { lo: String(range[0]), hi: String(range[1]), days: String(cfg.view_days ?? 8) })}</Text>
        </Box>
      )
    }
    const s5 = (sc?.scenarios ?? []).find((s: any) => s.id === (cfg.plein_regime?.scenario ?? 'S5'))
    const views: Record<string, any> = {
      today: period(m.today, false),
      week: period(m.weekView, true),
      forecast: (
        <Box flexDirection="column" gap={1}>
          {fc(l.week_label, m.week)}
          {fc(l.five_hour_label, m.five)}
          <Text dimColor>{`Calibration : ${fmtTokens(m.cal.seven_day.tokensPerPct ?? 0)} tokens par 1 % de la semaine (${m.cal.seven_day.n} échantillon(s), transcripts de ce PC seulement, non vérifié).`}</Text>
          <Text dimColor>{`Rythme mesuré (${unit}/h) : 2 h ${m.rates.recent.toFixed(2)} · jour ${m.rates.today.toFixed(2)} · 7 j ${m.rates.week.toFixed(2)}`}</Text>
        </Box>
      ),
      scenarios: (
        <Box flexDirection="column" gap={1}>
          <Text dimColor>Débit estimé de chaque scénario du mod scenarios (/scenarios), à partir de l'historique mesuré par type d'agent et modèle (non vérifié).</Text>
          {m.fit.rows.map((r: any) => (
            <Text {...(r.id === m.fit.best ? { bold: true } : {})}>{`${r.id} ${r.name} : ${fmtPct(r.pctPerHour)}/h actif · ${fmtPct(r.needPct)} d'ici le reset · ${r.fits === undefined ? '?' : r.fits ? l.fits : l.too_much}${r.id === m.fit.best ? ' ← le plus soutenu qui tient' : ''}`}</Text>
          ))}
          <Text dimColor>{`Reste ${fmtPct(m.fit.left)} · ${m.fit.hoursLeft === undefined ? '?' : Math.round(m.fit.hoursLeft)} h avant le reset, dont ${m.fit.activeHours === undefined ? '?' : Math.round(m.fit.activeHours)} h actives.`}</Text>
        </Box>
      ),
      codex: codexPane(),
      classement: current === 'classement' ? await classementPane() : null,
      history: current === 'history' ? await historyPane() : null,
      tps: current === 'tps' ? await tpsPane() : null,
      full: (
        <Box flexDirection="column" gap={1}>
          <Text bold color={m.full.suggest ? 'success' : undefined}>{m.full.suggest ? l.suggest_full : l.no_full}</Text>
          <Text dimColor>{`Seuils : plus de ${cfg.plein_regime?.min_left_pct} % restant au reset et moins de ${cfg.plein_regime?.max_hours_left} h avant le reset. Maintenant : ${fmtPct(m.full.left)} · ${m.full.hoursLeft === undefined ? '?' : Math.round(m.full.hoursLeft)} h.`}</Text>
          {s5 ? (
            <Box flexDirection="column" gap={1}>
              <Text>{`${s5.id} ${s5.name} : ${s5.summary ?? ''}`}</Text>
              <Code source={promptLine(s5, sc?.models)} language="text" />
              <Box flexDirection="row" gap={1}>
                <Button key="copy" hotkey="c" onPress={async press => {
                  const r = await $.ui.copy({ text: promptLine(s5, sc?.models), surface: press.surface })
                  await update($, copied, () => (r.isCopied ? `copié : ${s5.id}` : 'copie impossible : sélectionne le texte'))
                }}>Copier</Button>
                {last ? <Text dimColor>{last}</Text> : null}
              </Box>
            </Box>
          ) : <Text dimColor>{`Scénario ${cfg.plein_regime?.scenario} introuvable dans ${cfg.scenarios_file}.`}</Text>}
          <Text dimColor>Le mod ne lance rien : il suggère et montre le texte à coller.</Text>
        </Box>
      ),
    }
    return (
      <Box flexDirection="column" gap={1}>
        {header}
        {views[current] ?? views.today}
      </Box>
    )
  })
}

files.lib/transcripts.mjs:
// Canonical copy: lib/core/transcripts.mjs (repo root); usage/lib/transcripts.mjs and mods/*/lib/core copies are made by
// scripts/sync-libs.mjs: never edit a copy by hand.
// Shared, pure transcript parsing for the usage mod (and any mod that needs tokens: band imports it).
// No I/O here: lib/scan-node.mjs reads the files, this module turns lines into usage records and per-hour rows.
// Ideas ported from claude-goblin (MIT, github.com/data-goblin/claude-goblin): dedupe on message.id + requestId,
// incremental per-file state, list-price cost table.

/** Index of each figure in a usage vector. */
export const V = { in: 0, out: 1, cache_read: 2, cache_write_5m: 3, cache_write_1h: 4, msgs: 5, active_s: 6, cost: 7 }
export const zero = () => [0, 0, 0, 0, 0, 0, 0, 0]
export const addInto = (a, b, sign = 1) => {
  for (let i = 0; i < a.length; i++) a[i] += sign * (b[i] || 0)
  return a
}
/** All tokens of a vector: input + output + cache read + cache writes. */
export const tokensOf = v => v[0] + v[1] + v[2] + v[3] + v[4]

const HOUR = 3600000

/**
 * What kind of transcript a path is, from its place under ~/.claude/projects:
 *   <project>/<session>.jsonl                                  main thread (or a sub-conversation, see `isSubConversation`)
 *   <project>/<session>/subagents/agent-<id>.jsonl             Agent subagent
 *   <project>/<session>/subagents/workflows/wf_<id>/agent-*.jsonl  Workflow agent()
 *   .../journal.jsonl                                          Workflow journal (no tokens)
 */
export function kindOfPath(rel) {
  const parts = String(rel).replace(/\\/g, '/').split('/').filter(Boolean)
  const file = parts[parts.length - 1] || ''
  if (file === 'journal.jsonl') return 'journal'
  if (parts.includes('workflows')) return 'workflow'
  if (parts.includes('subagents')) return 'subagent'
  return 'main'
}

/** Project name from a cwd: the folder name, with any `.claude/worktrees/<lane>` tail removed. */
export function projectOf(cwd) {
  if (!cwd) return '?'
  const p = String(cwd).replace(/\\/g, '/').replace(/\/+$/, '')
  const base = p.replace(/\/\.claude\/worktrees\/[^/]+.*$/, '').replace(/\/\.worktrees\/[^/]+.*$/, '')
  const parts = base.split('/').filter(Boolean)
  return parts[parts.length - 1] || '?'
}

/** Model family from an id (opus, sonnet, haiku, fable) or the id itself. */
export function familyOf(model) {
  const m = String(model || '').toLowerCase()
  for (const f of ['fable', 'opus', 'sonnet', 'haiku']) if (m.includes(f)) return f
  return m || '?'
}

/** Price entry for a model id: exact id, then the id without a date suffix, then its family, then the default. */
export function priceFor(model, table) {
  const models = (table && table.models) || {}
  const id = String(model || '')
  if (models[id]) return models[id]
  const undated = id.replace(/-\d{8}$/, '')
  if (models[undated]) return models[undated]
  const fam = table && table.families && table.families[familyOf(id)]
  if (fam && models[fam]) return models[fam]
  return models[(table && table.default) || ''] || { in: 0, out: 0, cache_write_5m: 0, cache_write_1h: 0, cache_read: 0 }
}

/** List-price cost in USD of one request's tokens. */
export function costOf(v, model, table) {
  let p = priceFor(model, table)
  if (p.above && v[0] + v[2] + v[3] + v[4] > p.above.tokens) p = { ...p, ...p.above }
  return (v[0] * p.in + v[1] * p.out + v[2] * p.cache_read + v[3] * p.cache_write_5m + v[4] * (p.cache_write_1h ?? p.in * 2)) / 1e6
}

/**
 * The key an API response is counted once under: message.id + requestId. Every content block of one response is a
 * separate transcript line with its own uuid but the same message.id, and a fork, a resume or a subagent file can
 * repeat the same response, so the uuid is used only when the line has no message.id at all.
 */
export function keyOf(o) {
  const m = (o && o.message) || {}
  if (m.id) return `${m.id}|${o.requestId || ''}`
  return `|${o.requestId || o.uuid || o.timestamp || ''}`
}

/** Timestamp (ms) of a raw transcript line without parsing it, or 0. Only an unescaped top-level key matches. */
export function lineTs(line) {
  const i = line.indexOf('"timestamp":"')
  if (i < 0) return 0
  const t = Date.parse(line.slice(i + 13, line.indexOf('"', i + 13)))
  return Number.isFinite(t) ? t : 0
}

/** Whether a raw line sends a request (a prompt or a tool result): only those start a stream. Bookkeeping lines (queue,
 * hooks, PR links, titles, attachments) can be written at any time, even while a response streams. */
const sendsRequest = line => line.slice(0, 400).includes('"type":"user"')

/**
 * Output speed. One stream = one API response: it starts at the last transcript line written before its first
 * content block (the prompt or tool result that sent it) and ends at its last content block, so the time includes the
 * wait for the first token. TPS = output tokens (thinking included) / that time. Per hour, model and effort the state
 * keeps [output tokens, ms, streams, {bucket: streams}]; buckets are geometric (x1.15 from 1 tok/s) for the median
 * and the range. Streams under TPS_MIN_OUT output tokens or longer than TPS_MAX_MS are left out (latency or a pause,
 * not speed).
 */
export const TPS_MIN_OUT = 50
export const TPS_MAX_MS = 30 * 60000
const TPS_STEP = Math.log(1.15)
export const tpsBucket = tps => Math.max(0, Math.floor(Math.log(Math.max(tps, 1)) / TPS_STEP))
export const tpsOfBucket = b => Math.exp((b + 0.5) * TPS_STEP)
/** Adds (sign 1) or removes (sign -1) one stream in a TPS row [out, ms, n, hist]. */
export function tpsAdd(row, out, ms, sign = 1) {
  row[0] += sign * out
  row[1] += sign * ms
  row[2] += sign
  const b = tpsBucket(out / (ms / 1000))
  row[3][b] = (row[3][b] || 0) + sign
  if (!row[3][b]) delete row[3][b]
  return row
}
const STREAMS_KEPT = 10
/** Besides the last STREAMS_KEPT, a file keeps every stream of the hour before its newest (at most STREAMS_HOUR_MAX):
 * the exact streams behind the Panneau's « 30 min » row (cockpit Débit). */
export const STREAMS_HOUR_MS = HOUR
const STREAMS_HOUR_MAX = 400

/**
 * One usage record from a parsed transcript line, or null. Only assistant rows with a `message.usage` count;
 * `<synthetic>` rows (local notices) are skipped.
 */
export function usageOf(o) {
  if (!o || o.type !== 'assistant') return null
  const m = o.message
  if (!m || typeof m !== 'object' || !m.usage || typeof m.usage !== 'object') return null
  if (!m.model || m.model === '<synthetic>') return null
  const u = m.usage
  const cc = u.cache_creation && typeof u.cache_creation === 'object' ? u.cache_creation : null
  const cw = Number(u.cache_creation_input_tokens) || 0
  const cw1h = cc ? Number(cc.ephemeral_1h_input_tokens) || 0 : 0
  const cw5 = cc ? Number(cc.ephemeral_5m_input_tokens) || 0 : cw
  const ts = Date.parse(o.timestamp)
  if (!Number.isFinite(ts)) return null
  return {
    key: keyOf(o),
    ts,
    model: m.model,
    v: [Number(u.input_tokens) || 0, Number(u.output_tokens) || 0, Number(u.cache_read_input_tokens) || 0, cw5, cw1h, 1, 0, 0],
    effort: o.effort || o.perTurnEffort || '',
    agent: o.attributionAgent || '',
    skill: o.attributionSkill || '',
    mcp: o.attributionMcpServer || '',
    session: o.sessionId || '',
    cwd: o.cwd || '',
    entrypoint: o.entrypoint || '',
  }
}

/** Fresh per-file state: what the incremental scanner keeps for each transcript. */
export const newFileState = (kind = 'main') => ({
  kind, offset: 0, session: '', cwd: '', entrypoint: '', title: '', agent: '', firstOrigin: '', lastTs: 0,
  rows: {}, recent: {}, keys: {}, lineTs: 0, tps: {}, streams: [],
})

const RECENT = 200

/** Puts one stream's timing in the file state, replacing what an earlier line of the same response gave. */
function timeStream(st, r, rec) {
  st.tps = st.tps || {}
  st.streams = st.streams || []
  if (rec.t) {
    const old = st.tps[rec.t.row]
    if (old) {
      tpsAdd(old, rec.t.out, rec.t.ms, -1)
      if (old[2] <= 0) delete st.tps[rec.t.row]
    }
  }
  const out = r.v[V.out]
  const ms = r.ts - rec.start
  rec.t = null
  const i = st.streams.findIndex(x => x.k === r.key)
  if (i >= 0) st.streams.splice(i, 1)
  if (!(rec.start > 0) || ms <= 0 || ms > TPS_MAX_MS || out < TPS_MIN_OUT) return
  const row = `${Math.floor(rec.start / HOUR) * HOUR}|${r.model}|${r.effort}`
  tpsAdd((st.tps[row] = st.tps[row] || [0, 0, 0, {}]), out, ms)
  rec.t = { row, out, ms }
  st.streams.push({ k: r.key, ts: r.ts, model: r.model, effort: r.effort, out, ms })
  while (st.streams.length > STREAMS_KEPT && (st.streams.length > STREAMS_HOUR_MAX || st.streams[0].ts < r.ts - STREAMS_HOUR_MS)) st.streams.shift()
}

/**
 * Feeds one transcript line into a file state. `claim(key)` says whether this response is new across files
 * (true) or already counted in another file (false); `prices` turns tokens into a list-price cost.
 * Rows are keyed `hourMs|model|effort|skill|mcp|agent`, each a usage vector.
 * The same response repeated in one file (one line per content block) replaces its earlier figures.
 */
export function feedLine(st, line, { prices, claim = () => true, idleGapS = 300 } = {}) {
  if (!line || line.length < 20) return
  const hasUsage = line.includes('"usage"')
  const wantsMeta = (!st.firstOrigin && line.includes('"origin"')) || line.includes('"custom-title"') || line.includes('"agent-name"')
  const ts = lineTs(line)
  if (!hasUsage && !wantsMeta) {
    if (ts && sendsRequest(line)) st.lineTs = ts
    return
  }
  let o
  try {
    o = JSON.parse(line)
  } catch {
    return
  }
  if (o.type === 'custom-title' && o.customTitle) st.title = String(o.customTitle).slice(0, 120)
  if (o.type === 'agent-name' && o.agentName) st.agent = st.agent || String(o.agentName).slice(0, 60)
  if (!st.firstOrigin && o.type === 'user' && o.origin && o.origin.kind) st.firstOrigin = String(o.origin.kind)
  const r = usageOf(o)
  const before = st.lineTs || 0
  if (ts && (r || o.type === 'user')) st.lineTs = ts
  if (!r) return
  st.session = st.session || r.session
  st.cwd = st.cwd || r.cwd
  st.entrypoint = st.entrypoint || r.entrypoint
  if (r.agent && !st.agent) st.agent = r.agent
  const prev = st.recent[r.key]
  let start = before
  if (!prev) {
    if (st.keys[r.key] !== undefined || !claim(r.key)) return // counted already (here, or in another file)
    if (st.lastTs && r.ts > st.lastTs) r.v[V.active_s] = Math.min((r.ts - st.lastTs) / 1000, idleGapS)
    if (r.ts > st.lastTs) st.lastTs = r.ts
  } else {
    // a later line of the same response: drop the earlier figures, keep its active time and message count
    const old = st.rows[prev.row]
    if (old) addInto(old, prev.v, -1)
    r.v[V.active_s] = prev.v[V.active_s]
    start = prev.start
  }
  r.v[V.cost] = costOf(r.v, r.model, prices)
  const hour = Math.floor(r.ts / HOUR) * HOUR
  const row = `${hour}|${r.model}|${r.effort}|${r.skill}|${r.mcp}|${r.agent}`
  st.rows[row] = addInto(st.rows[row] || zero(), r.v)
  const rec = { row, v: r.v, start, t: prev ? prev.t : null }
  timeStream(st, r, rec)
  delete st.recent[r.key]
  st.recent[r.key] = rec
  st.keys[r.key] = hour
  const ks = Object.keys(st.recent)
  if (ks.length > RECENT) for (const k of ks.slice(0, ks.length - RECENT)) delete st.recent[k]
}

/** Drops rows and keys older than `fromMs` (retention). */
export function prune(st, fromMs) {
  for (const k of Object.keys(st.rows)) if (Number(k.split('|')[0]) < fromMs) delete st.rows[k]
  for (const k of Object.keys(st.tps || {})) if (Number(k.split('|')[0]) < fromMs) delete st.tps[k]
  for (const [k, h] of Object.entries(st.keys)) if (h < fromMs) delete st.keys[k]
}

/** Whether a main transcript is a sub-conversation: its first prompt came from another session (non vérifié). */
export const isSubConversation = (st, rule = 'peer') => st.kind === 'main' && Boolean(rule) && st.firstOrigin === rule

const pad = n => String(n).padStart(2, '0')
/** Local day key YYYY-MM-DD for a time, `tzMin` minutes east of UTC. */
export function dayKey(ms, tzMin = 0) {
  const d = new Date(ms + tzMin * 60000)
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`
}

const bump = (map, key, v) => {
  const k = key || '?'
  map[k] = addInto(map[k] || zero(), v)
}

/**
 * Totals over all file states, for the views: hourly global vectors, per-day breakdowns (project, model, kind,
 * surface, skill, mcp, session, effort) for the last `days` days, session labels, and per-(kind, family) totals with
 * active seconds (the measured burn per agent-hour that the scenario estimates use).
 */
export function aggregate(files, { now, tzMin = 0, days = 8, surfaces = {}, subRule = 'peer' } = {}) {
  const from = now - days * 86400000
  const out = { generated: now, tzMin, hourly: {}, hourlyModel: {}, days: {}, sessions: {}, rates: {}, tps: {}, streams: [], tpsHourly: {}, recentStreams: [] }
  for (const st of Object.values(files)) {
    if (st.kind === 'journal') continue
    const kind = isSubConversation(st, subRule) ? 'subconversation' : st.kind
    const surface = surfaces[st.entrypoint] || st.entrypoint || '?'
    const project = projectOf(st.cwd)
    const sid = st.session || '?'
    if (kind === 'main' || kind === 'subconversation') {
      const s = (out.sessions[sid] = out.sessions[sid] || { title: '', project, kind, surface })
      if (st.title) s.title = st.title
    } else if (!out.sessions[sid]) out.sessions[sid] = { title: '', project, kind: 'main', surface }
    for (const [rk, t] of Object.entries(st.tps || {})) {
      const [h, model, effort] = rk.split('|')
      if (Number(h) < from) continue
      for (const row of [(out.tps[`${model}|${effort}`] = out.tps[`${model}|${effort}`] || [0, 0, 0, {}]), (out.tpsHourly[rk] = out.tpsHourly[rk] || [0, 0, 0, {}])]) {
        row[0] += t[0]
        row[1] += t[1]
        row[2] += t[2]
        for (const [b, n] of Object.entries(t[3])) row[3][b] = (row[3][b] || 0) + n
      }
    }
    for (const x of st.streams || []) {
      if (x.ts < from) continue
      const one = { ts: x.ts, model: x.model, effort: x.effort, out: x.out, ms: x.ms, kind, project, session: sid }
      out.streams.push(one)
      if (x.ts >= now - STREAMS_HOUR_MS) out.recentStreams.push(one)
    }
    for (const [rk, v] of Object.entries(st.rows)) {
      const [h, model, effort, skill, mcp] = rk.split('|')
      const hour = Number(h)
      const fam = familyOf(model)
      const rate = (out.rates[`${kind}|${fam}`] = out.rates[`${kind}|${fam}`] || zero())
      addInto(rate, v)
      bump(out.hourly, String(hour), v)
      if (hour < from) continue
      const hm = (out.hourlyModel[String(hour)] = out.hourlyModel[String(hour)] || {})
      bump(hm, model, v)
      const day = dayKey(hour, tzMin)
      const d = (out.days[day] = out.days[day] || { total: zero(), project: {}, model: {}, kind: {}, surface: {}, skill: {}, mcp: {}, session: {}, effort: {} })
      addInto(d.total, v)
      bump(d.project, project, v)
      bump(d.model, model, v)
      bump(d.kind, kind, v)
      bump(d.surface, surface, v)
      if (skill) bump(d.skill, skill, v)
      if (mcp) bump(d.mcp, mcp, v)
      bump(d.session, sid, v)
      bump(d.effort, effort || '?', v)
    }
  }
  out.streams = out.streams.sort((a, b) => b.ts - a.ts).slice(0, STREAMS_KEPT * 3)
  // tpsHourly: the same TPS rows per `hour|model|effort`, so a reader can cut its own windows (cockpit's Débit);
  // recentStreams: every stream of the last hour, newest first
  out.recentStreams = out.recentStreams.sort((a, b) => b.ts - a.ts).slice(0, 4000)
  return out
}

